import numpy as np
L=open('answer.xyz').read().split('\n'); n=int(L[0]); s=[];x=[]
for l in L[2:2+n]:
    p=l.split(); s.append(p[0]); x.append([float(v) for v in p[1:4]])
x=np.array(x)
cov={'H':0.31,'C':0.76,'O':0.66,'F':0.57,'Cr':1.39}
D=np.linalg.norm(x[:,None]-x[None],axis=-1)
bonds=set()
for i in range(n):
  for j in range(i+1,n):
    if D[i,j]<(cov[s[i]]+cov[s[j]])*1.3: bonds.add((i,j))
# 1-3
adj={i:set() for i in range(n)}
for i,j in bonds: adj[i].add(j); adj[j].add(i)
bad=[]
for i in range(n):
  for j in range(i+1,n):
    if (i,j) in bonds: continue
    if adj[i]&adj[j]: continue
    # 1-4
    if any(k in adj[j] for a in adj[i] for k in adj[a]): continue
    if D[i,j] < (cov[s[i]]+cov[s[j]])*1.2: bad.append((i,s[i],j,s[j],round(D[i,j],2)))
print(len(bad)); print(bad[:20])
